10	    static constexpr bool is_all_join = STRICTNESS == JoinStrictness::All;
11	    static constexpr bool is_asof_join = STRICTNESS == JoinStrictness::Asof;
12	    static constexpr bool is_semi_join = STRICTNESS == JoinStrictness::Semi;
13	    static constexpr bool is_anti_join = STRICTNESS == JoinStrictness::Anti;
14	    static constexpr bool is_any_or_semi_join = is_any_join || STRICTNESS == JoinStrictness::RightAny || (is_semi_join && KIND == JoinKind::Left);
15	
16	    static constexpr bool left = KIND == JoinKind::Left;
17	    static constexpr bool right = KIND == JoinKind::Right;
18	    static constexpr bool inner = KIND == JoinKind::Inner;
19	    static constexpr bool full = KIND == JoinKind::Full;
20	
21	    /** Whether we may need duplicate rows from the left table.
22	      * For example, when we have row (key1, attr1) in left table
23	      * and rows (key1, attr2), (key1, attr3) in right table,
24	      * then we need to duplicate row (key1, attr1) for each of joined rows from right table, so result will be
25	      * (key1, attr1, key1, attr2)
26	      * (key1, attr1, key1, attr3)
27	      */
28	    static constexpr bool need_replication = is_all_join || (is_any_join && right) || (is_semi_join && right);
29	
30	    /// Whether we need to filter rows from the left table that do not have matches in the right table.
31	    static constexpr bool need_filter = !need_replication && (inner || right || (is_semi_join && left) || (is_anti_join && left));
32	
33	    /// Whether we need to add default values for columns from the left table.
34	    static constexpr bool add_missing = (left || full) && !is_semi_join;
35	
36	    /// Whether we need to store flags for rows from the right table table
37	    /// that indicates if they have matches in the left table.
38	    static constexpr bool need_flags = MapGetter<KIND, STRICTNESS, std::is_same_v<std::decay_t<Map>, HashJoin::MapsAll>>::flagged;
39	
40	    static constexpr bool is_maps_all = std::is_same_v<std::decay_t<Map>, HashJoin::MapsAll>;
41	};
