15	/// Keep already joined rows to prevent duplication if many disjuncts
16	///   if for a particular pair of rows condition looks like TRUE or TRUE or TRUE
17	///   we want to have it once in resultset
18	template<>
19	class KnownRowsHolder<true>
20	{
21	public:
22	    using Type = PairNoInit<const Columns *, DB::RowRef::SizeT>;
23	
24	private:
25	    static const size_t MAX_LINEAR = 16; // threshold to switch from Array to Set
26	    using ArrayHolder = std::array<Type, MAX_LINEAR>;
27	    using SetHolder = std::set<Type>;
28	    using SetHolderPtr = std::unique_ptr<SetHolder>;
29	
30	    ArrayHolder array_holder;
31	    SetHolderPtr set_holder_ptr;
32	
33	    size_t items;
34	
35	public:
36	    KnownRowsHolder()
37	        : items(0)
38	    {
39	    }
40	
41	    template<class InputIt>
42	    void add(InputIt from, InputIt to)
43	    {
44	        const size_t new_items = std::distance(from, to);
45	        if (items + new_items <= MAX_LINEAR)
46	        {
47	            std::copy(from, to, std::begin(array_holder) + items);
48	        }
49	        else
50	        {
51	            if (items <= MAX_LINEAR)
52	            {
53	                set_holder_ptr = std::make_unique<SetHolder>();
54	                set_holder_ptr->insert(std::cbegin(array_holder), std::cbegin(array_holder) + items);
55	            }
56	            set_holder_ptr->insert(from, to);
57	        }
58	        items += new_items;
59	    }
60	
61	    template<class Needle>
62	    bool isKnown(const Needle & needle)
63	    {
64	        return items <= MAX_LINEAR
65	            ? std::find(std::cbegin(array_holder), std::cbegin(array_holder) + items, needle) != std::cbegin(array_holder) + items
66	            : set_holder_ptr->find(needle) != set_holder_ptr->end();
67	    }
68	};
